INSERT INTO tarot_cards (id, deck_order, arcana_type, major_number, suit, rank_number, name, image_path, meaning, advice, yes_no, yes_no_meaning) VALUES
  ('ace-of-wands', 22, 'minor', NULL, 'wands', 1, 'Ace of Wands', '/cards/minor/wands/ace.svg', 'A spark of inspiration opens a bold creative path.', 'Begin while the energy is fresh and give the idea a real first step.', 'yes', 'The Ace of Wands leans yes: begin while the energy is fresh and give the idea a real first step.'),
  ('two-of-wands', 23, 'minor', NULL, 'wands', 2, 'Two of Wands', '/cards/minor/wands/two.svg', 'A future is taking shape through planning and a choice of direction.', 'Look beyond what is familiar, then commit to the path with room to grow.', 'maybe', 'The Two of Wands remains conditional: look beyond what is familiar, then commit to the path with room to grow.'),
  ('three-of-wands', 24, 'minor', NULL, 'wands', 3, 'Three of Wands', '/cards/minor/wands/three.svg', 'Early effort expands as opportunities and wider horizons come into view.', 'Keep building and be ready to meet the response your work attracts.', 'yes', 'The Three of Wands leans yes: keep building and be ready to meet the response your work attracts.'),
  ('four-of-wands', 25, 'minor', NULL, 'wands', 4, 'Four of Wands', '/cards/minor/wands/four.svg', 'Stability, welcome, and shared celebration create a strong foundation.', 'Mark the milestone and let supportive people share in it.', 'yes', 'The Four of Wands leans yes: mark the milestone and let supportive people share in it.'),
  ('five-of-wands', 26, 'minor', NULL, 'wands', 5, 'Five of Wands', '/cards/minor/wands/five.svg', 'Competing aims create friction, noise, or a test of confidence.', 'Turn rivalry into useful practice and refuse conflict that has no purpose.', 'maybe', 'The Five of Wands remains conditional: turn rivalry into useful practice and refuse conflict that has no purpose.'),
  ('six-of-wands', 27, 'minor', NULL, 'wands', 6, 'Six of Wands', '/cards/minor/wands/six.svg', 'Recognition follows determined effort and visible progress.', 'Accept the encouragement, but keep your confidence tied to honest work.', 'yes', 'The Six of Wands leans yes: accept the encouragement, but keep your confidence tied to honest work.'),
  ('seven-of-wands', 28, 'minor', NULL, 'wands', 7, 'Seven of Wands', '/cards/minor/wands/seven.svg', 'You hold valuable ground while pressure tests your resolve.', 'Defend what matters with clear boundaries instead of fighting every challenge.', 'yes', 'The Seven of Wands leans yes: defend what matters with clear boundaries instead of fighting every challenge.'),
  ('eight-of-wands', 29, 'minor', NULL, 'wands', 8, 'Eight of Wands', '/cards/minor/wands/eight.svg', 'Events accelerate, messages arrive, and momentum clears delay.', 'Act promptly and keep communication direct while the way is open.', 'yes', 'The Eight of Wands leans yes: act promptly and keep communication direct while the way is open.'),
  ('nine-of-wands', 30, 'minor', NULL, 'wands', 9, 'Nine of Wands', '/cards/minor/wands/nine.svg', 'Resilience is strong, though past strain makes you watchful.', 'Protect your energy and take the next step without expecting every wound to repeat.', 'maybe', 'The Nine of Wands remains conditional: protect your energy and take the next step without expecting every wound to repeat.'),
  ('ten-of-wands', 31, 'minor', NULL, 'wands', 10, 'Ten of Wands', '/cards/minor/wands/ten.svg', 'Responsibility has become heavy and success now carries a burden.', 'Delegate, simplify, and put down work that is no longer truly yours.', 'no', 'The Ten of Wands leans no: delegate, simplify, and put down work that is no longer truly yours.'),
  ('page-of-wands', 32, 'minor', NULL, 'wands', 11, 'Page of Wands', '/cards/minor/wands/page.svg', 'Curiosity brings a lively message, experiment, or new creative interest.', 'Explore with courage and let beginner energy teach you through action.', 'yes', 'The Page of Wands leans yes: explore with courage and let beginner energy teach you through action.'),
  ('knight-of-wands', 33, 'minor', NULL, 'wands', 12, 'Knight of Wands', '/cards/minor/wands/knight.svg', 'Passion charges ahead quickly, bringing adventure and possible impatience.', 'Use the momentum, but choose a direction before speed scatters your effort.', 'maybe', 'The Knight of Wands remains conditional: use the momentum, but choose a direction before speed scatters your effort.'),
  ('queen-of-wands', 34, 'minor', NULL, 'wands', 13, 'Queen of Wands', '/cards/minor/wands/queen.svg', 'Warm confidence and creative independence draw others toward your vision.', 'Trust your presence, encourage others, and do not shrink your ambition.', 'yes', 'The Queen of Wands leans yes: trust your presence, encourage others, and do not shrink your ambition.'),
  ('king-of-wands', 35, 'minor', NULL, 'wands', 14, 'King of Wands', '/cards/minor/wands/king.svg', 'Mature vision turns inspiration into decisive and ethical leadership.', 'Lead from the larger purpose and give others space to contribute.', 'yes', 'The King of Wands leans yes: lead from the larger purpose and give others space to contribute.'),
  ('ace-of-cups', 36, 'minor', NULL, 'cups', 1, 'Ace of Cups', '/cards/minor/cups/ace.svg', 'The heart opens to new affection, compassion, and emotional renewal.', 'Receive the feeling honestly and let care flow without forcing an outcome.', 'yes', 'The Ace of Cups leans yes: receive the feeling honestly and let care flow without forcing an outcome.'),
  ('two-of-cups', 37, 'minor', NULL, 'cups', 2, 'Two of Cups', '/cards/minor/cups/two.svg', 'Mutual recognition creates partnership, attraction, or sincere agreement.', 'Meet the other person as an equal and speak from the heart.', 'yes', 'The Two of Cups leans yes: meet the other person as an equal and speak from the heart.'),
  ('three-of-cups', 38, 'minor', NULL, 'cups', 3, 'Three of Cups', '/cards/minor/cups/three.svg', 'Friendship, community, and shared joy bring emotional support.', 'Celebrate together and remember who genuinely shows up for you.', 'yes', 'The Three of Cups leans yes: celebrate together and remember who genuinely shows up for you.'),
  ('four-of-cups', 39, 'minor', NULL, 'cups', 4, 'Four of Cups', '/cards/minor/cups/four.svg', 'Emotional withdrawal makes an available gift difficult to notice.', 'Pause the comparison and look again at what is quietly being offered.', 'no', 'The Four of Cups leans no: pause the comparison and look again at what is quietly being offered.'),
  ('five-of-cups', 40, 'minor', NULL, 'cups', 5, 'Five of Cups', '/cards/minor/cups/five.svg', 'Loss draws attention to what spilled while something meaningful remains.', 'Honor the disappointment, then turn toward the support that is still present.', 'no', 'The Five of Cups leans no: honor the disappointment, then turn toward the support that is still present.'),
  ('six-of-cups', 41, 'minor', NULL, 'cups', 6, 'Six of Cups', '/cards/minor/cups/six.svg', 'Memory, innocence, or a familiar bond returns with gentle warmth.', 'Welcome the kindness of the past without pretending you must live there again.', 'yes', 'The Six of Cups leans yes: welcome the kindness of the past without pretending you must live there again.'),
  ('seven-of-cups', 42, 'minor', NULL, 'cups', 7, 'Seven of Cups', '/cards/minor/cups/seven.svg', 'Many appealing possibilities blur the difference between vision and illusion.', 'Narrow the choices and test one dream against reality before committing.', 'uncertain', 'The Seven of Cups is not clear yet: narrow the choices and test one dream against reality before committing.'),
  ('eight-of-cups', 43, 'minor', NULL, 'cups', 8, 'Eight of Cups', '/cards/minor/cups/eight.svg', 'A once-meaningful situation no longer nourishes the heart.', 'Leave with honesty and move toward the deeper fulfillment you now need.', 'no', 'The Eight of Cups leans no: leave with honesty and move toward the deeper fulfillment you now need.'),
  ('nine-of-cups', 44, 'minor', NULL, 'cups', 9, 'Nine of Cups', '/cards/minor/cups/nine.svg', 'Contentment and gratitude make a heartfelt wish feel close.', 'Enjoy what is here and ask whether the wish also serves your deeper values.', 'yes', 'The Nine of Cups leans yes: enjoy what is here and ask whether the wish also serves your deeper values.'),
  ('ten-of-cups', 45, 'minor', NULL, 'cups', 10, 'Ten of Cups', '/cards/minor/cups/ten.svg', 'Emotional harmony, belonging, and lasting connection surround the home.', 'Nurture the bonds that make joy sustainable and shared.', 'yes', 'The Ten of Cups leans yes: nurture the bonds that make joy sustainable and shared.'),
  ('page-of-cups', 46, 'minor', NULL, 'cups', 11, 'Page of Cups', '/cards/minor/cups/page.svg', 'A tender message or intuitive discovery invites emotional openness.', 'Stay curious about the feeling and respond with sincerity rather than assumption.', 'maybe', 'The Page of Cups remains conditional: stay curious about the feeling and respond with sincerity rather than assumption.'),
  ('knight-of-cups', 47, 'minor', NULL, 'cups', 12, 'Knight of Cups', '/cards/minor/cups/knight.svg', 'Romance, imagination, or an ideal draws the heart forward.', 'Follow the invitation, but keep one foot on the ground as promises unfold.', 'yes', 'The Knight of Cups leans yes: follow the invitation, but keep one foot on the ground as promises unfold.'),
  ('queen-of-cups', 48, 'minor', NULL, 'cups', 13, 'Queen of Cups', '/cards/minor/cups/queen.svg', 'Deep empathy and intuition create a calm space for truth.', 'Listen compassionately while preserving the boundaries that keep care healthy.', 'yes', 'The Queen of Cups leans yes: listen compassionately while preserving the boundaries that keep care healthy.'),
  ('king-of-cups', 49, 'minor', NULL, 'cups', 14, 'King of Cups', '/cards/minor/cups/king.svg', 'Emotional maturity steadies strong feelings without suppressing them.', 'Respond with compassion and self-command, especially when others are reactive.', 'yes', 'The King of Cups leans yes: respond with compassion and self-command, especially when others are reactive.'),
  ('ace-of-swords', 50, 'minor', NULL, 'swords', 1, 'Ace of Swords', '/cards/minor/swords/ace.svg', 'A clean insight cuts through confusion and reveals a new truth.', 'Name the issue plainly and use clarity in service of a fair decision.', 'yes', 'The Ace of Swords leans yes: name the issue plainly and use clarity in service of a fair decision.'),
  ('two-of-swords', 51, 'minor', NULL, 'swords', 2, 'Two of Swords', '/cards/minor/swords/two.svg', 'A guarded stalemate delays a choice that cannot remain suspended forever.', 'Remove the blindfold gently, gather the missing fact, and decide from balance.', 'uncertain', 'The Two of Swords is not clear yet: remove the blindfold gently, gather the missing fact, and decide from balance.'),
  ('three-of-swords', 52, 'minor', NULL, 'swords', 3, 'Three of Swords', '/cards/minor/swords/three.svg', 'A painful truth, separation, or disappointment asks to be acknowledged.', 'Let the feeling move through you and avoid turning hurt into a permanent story.', 'no', 'The Three of Swords leans no: let the feeling move through you and avoid turning hurt into a permanent story.'),
  ('four-of-swords', 53, 'minor', NULL, 'swords', 4, 'Four of Swords', '/cards/minor/swords/four.svg', 'Rest and mental quiet are needed after pressure or conflict.', 'Pause before answering; recovery is productive when it restores clear thought.', 'no', 'The Four of Swords leans no: pause before answering; recovery is productive when it restores clear thought.'),
  ('five-of-swords', 54, 'minor', NULL, 'swords', 5, 'Five of Swords', '/cards/minor/swords/five.svg', 'Conflict may produce a hollow victory or leave trust damaged.', 'Choose dignity over winning and step away from tactics that cost too much.', 'no', 'The Five of Swords leans no: choose dignity over winning and step away from tactics that cost too much.'),
  ('six-of-swords', 55, 'minor', NULL, 'swords', 6, 'Six of Swords', '/cards/minor/swords/six.svg', 'A difficult passage moves gradually toward calmer conditions.', 'Take what you have learned, accept support, and keep moving away from turmoil.', 'yes', 'The Six of Swords leans yes: take what you have learned, accept support, and keep moving away from turmoil.'),
  ('seven-of-swords', 56, 'minor', NULL, 'swords', 7, 'Seven of Swords', '/cards/minor/swords/seven.svg', 'Strategy, secrecy, or avoidance complicates the path.', 'Act cleverly but transparently; shortcuts that betray trust will return as problems.', 'no', 'The Seven of Swords leans no: act cleverly but transparently; shortcuts that betray trust will return as problems.'),
  ('eight-of-swords', 57, 'minor', NULL, 'swords', 8, 'Eight of Swords', '/cards/minor/swords/eight.svg', 'Fear and restrictive beliefs make the available options hard to see.', 'Question the thought that says you are trapped and take one small freeing action.', 'no', 'The Eight of Swords leans no: question the thought that says you are trapped and take one small freeing action.'),
  ('nine-of-swords', 58, 'minor', NULL, 'swords', 9, 'Nine of Swords', '/cards/minor/swords/nine.svg', 'Anxiety magnifies danger in the dark and exhausts the mind.', 'Bring the fear into daylight, seek support, and separate facts from imagined outcomes.', 'no', 'The Nine of Swords leans no: bring the fear into daylight, seek support, and separate facts from imagined outcomes.'),
  ('ten-of-swords', 59, 'minor', NULL, 'swords', 10, 'Ten of Swords', '/cards/minor/swords/ten.svg', 'A painful cycle reaches its final limit and cannot continue unchanged.', 'Accept the ending, protect your recovery, and allow a different beginning to emerge.', 'no', 'The Ten of Swords leans no: accept the ending, protect your recovery, and allow a different beginning to emerge.'),
  ('page-of-swords', 60, 'minor', NULL, 'swords', 11, 'Page of Swords', '/cards/minor/swords/page.svg', 'Alert curiosity seeks facts, asks questions, and watches for change.', 'Research carefully and speak with precision rather than reacting to every signal.', 'maybe', 'The Page of Swords remains conditional: research carefully and speak with precision rather than reacting to every signal.'),
  ('knight-of-swords', 61, 'minor', NULL, 'swords', 12, 'Knight of Swords', '/cards/minor/swords/knight.svg', 'Focused intellect moves fast and confronts obstacles directly.', 'Advance with courage, but slow enough to hear what your certainty might miss.', 'maybe', 'The Knight of Swords remains conditional: advance with courage, but slow enough to hear what your certainty might miss.'),
  ('queen-of-swords', 62, 'minor', NULL, 'swords', 13, 'Queen of Swords', '/cards/minor/swords/queen.svg', 'Clear perception and honest boundaries cut away confusion.', 'Say what is true with compassion and let experience sharpen, not harden, you.', 'yes', 'The Queen of Swords leans yes: say what is true with compassion and let experience sharpen, not harden, you.'),
  ('king-of-swords', 63, 'minor', NULL, 'swords', 14, 'King of Swords', '/cards/minor/swords/king.svg', 'Reason, fairness, and disciplined judgment guide a consequential decision.', 'Use evidence, define the standard, and keep personal bias out of the verdict.', 'yes', 'The King of Swords leans yes: use evidence, define the standard, and keep personal bias out of the verdict.'),
  ('ace-of-pentacles', 64, 'minor', NULL, 'pentacles', 1, 'Ace of Pentacles', '/cards/minor/pentacles/ace.svg', 'A tangible opportunity offers the seed of prosperity, work, or wellbeing.', 'Ground the opportunity in a practical plan and care for it consistently.', 'yes', 'The Ace of Pentacles leans yes: ground the opportunity in a practical plan and care for it consistently.'),
  ('two-of-pentacles', 65, 'minor', NULL, 'pentacles', 2, 'Two of Pentacles', '/cards/minor/pentacles/two.svg', 'Several priorities move at once and require flexible balance.', 'Adjust the rhythm, protect essentials, and avoid promising more than you can carry.', 'maybe', 'The Two of Pentacles remains conditional: adjust the rhythm, protect essentials, and avoid promising more than you can carry.'),
  ('three-of-pentacles', 66, 'minor', NULL, 'pentacles', 3, 'Three of Pentacles', '/cards/minor/pentacles/three.svg', 'Skill grows through collaboration, feedback, and careful craftsmanship.', 'Contribute your strength, respect expertise, and build to a shared standard.', 'yes', 'The Three of Pentacles leans yes: contribute your strength, respect expertise, and build to a shared standard.'),
  ('four-of-pentacles', 67, 'minor', NULL, 'pentacles', 4, 'Four of Pentacles', '/cards/minor/pentacles/four.svg', 'Holding tightly to security can preserve resources but restrict healthy flow.', 'Protect what matters without letting fear make every decision for you.', 'maybe', 'The Four of Pentacles remains conditional: protect what matters without letting fear make every decision for you.'),
  ('five-of-pentacles', 68, 'minor', NULL, 'pentacles', 5, 'Five of Pentacles', '/cards/minor/pentacles/five.svg', 'Material strain or exclusion creates worry and a sense of scarcity.', 'Ask for practical help and notice the door that hardship has made easy to overlook.', 'no', 'The Five of Pentacles leans no: ask for practical help and notice the door that hardship has made easy to overlook.'),
  ('six-of-pentacles', 69, 'minor', NULL, 'pentacles', 6, 'Six of Pentacles', '/cards/minor/pentacles/six.svg', 'Resources are exchanged, raising questions of generosity, power, and fairness.', 'Give or receive with clear terms so support preserves dignity on both sides.', 'yes', 'The Six of Pentacles leans yes: give or receive with clear terms so support preserves dignity on both sides.'),
  ('seven-of-pentacles', 70, 'minor', NULL, 'pentacles', 7, 'Seven of Pentacles', '/cards/minor/pentacles/seven.svg', 'Patient investment reaches a point of assessment before the next effort.', 'Review what is growing, improve the method, and allow worthwhile results time.', 'maybe', 'The Seven of Pentacles remains conditional: review what is growing, improve the method, and allow worthwhile results time.'),
  ('eight-of-pentacles', 71, 'minor', NULL, 'pentacles', 8, 'Eight of Pentacles', '/cards/minor/pentacles/eight.svg', 'Focused repetition develops mastery and dependable results.', 'Practice the essential skill, welcome correction, and let quality accumulate.', 'yes', 'The Eight of Pentacles leans yes: practice the essential skill, welcome correction, and let quality accumulate.'),
  ('nine-of-pentacles', 72, 'minor', NULL, 'pentacles', 9, 'Nine of Pentacles', '/cards/minor/pentacles/nine.svg', 'Self-reliance and cultivated comfort reflect disciplined progress.', 'Enjoy what you have built and keep independence connected to gratitude.', 'yes', 'The Nine of Pentacles leans yes: enjoy what you have built and keep independence connected to gratitude.'),
  ('ten-of-pentacles', 73, 'minor', NULL, 'pentacles', 10, 'Ten of Pentacles', '/cards/minor/pentacles/ten.svg', 'Long-term security grows through legacy, family, and shared foundations.', 'Plan beyond the immediate win and protect what can support others over time.', 'yes', 'The Ten of Pentacles leans yes: plan beyond the immediate win and protect what can support others over time.'),
  ('page-of-pentacles', 74, 'minor', NULL, 'pentacles', 11, 'Page of Pentacles', '/cards/minor/pentacles/page.svg', 'A practical message invites study, planning, or a grounded new venture.', 'Learn the basics, define the next task, and prove the idea through steady work.', 'yes', 'The Page of Pentacles leans yes: learn the basics, define the next task, and prove the idea through steady work.'),
  ('knight-of-pentacles', 75, 'minor', NULL, 'pentacles', 12, 'Knight of Pentacles', '/cards/minor/pentacles/knight.svg', 'Reliable effort advances slowly but rarely abandons the task.', 'Keep the routine honest and consistent; progress matters more than excitement.', 'yes', 'The Knight of Pentacles leans yes: keep the routine honest and consistent; progress matters more than excitement.'),
  ('queen-of-pentacles', 76, 'minor', NULL, 'pentacles', 13, 'Queen of Pentacles', '/cards/minor/pentacles/queen.svg', 'Resourceful care creates comfort, health, and practical abundance.', 'Nurture people and plans in ways that remain sustainable for you.', 'yes', 'The Queen of Pentacles leans yes: nurture people and plans in ways that remain sustainable for you.'),
  ('king-of-pentacles', 77, 'minor', NULL, 'pentacles', 14, 'King of Pentacles', '/cards/minor/pentacles/king.svg', 'Material leadership turns experience into stable and generous stewardship.', 'Make the sound long-term choice and use success responsibly.', 'yes', 'The King of Pentacles leans yes: make the sound long-term choice and use success responsibly.');
